// Alkışla yanan lamba: 1 sn içinde iki alkış LED'i yakar ya da söndürür.
const int SES_PIN = 2;
const int LED_PIN = 9;
const int SES_VAR = HIGH;                // Modülün DO'su ses varken HIGH olur. Tersse LOW yaz.
const unsigned long SESSIZLIK = 150;     // ms; bu kadar sessizlikten sonraki ses yeni alkıştır
const unsigned long ALKIS_ARASI = 1000;  // ms; ikinci alkış bu süre içinde gelmeli

bool lamba = false;
byte alkisSayisi = 0;
unsigned long sonSes = 0;     // en son ses duyulan an
unsigned long ilkAlkis = 0;   // çiftin ilk alkışının anı

void setup() {
  Serial.begin(9600);
  pinMode(SES_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("Iki kez alkislayin.");
}

void loop() {
  unsigned long simdi = millis();

  if (digitalRead(SES_PIN) == SES_VAR) {
    // Sessizlikten sonra gelen ilk ses yeni bir alkıştır; yankı ve titreşim sayılmaz.
    if (simdi - sonSes > SESSIZLIK) {
      if (alkisSayisi == 1 && simdi - ilkAlkis <= ALKIS_ARASI) {
        alkisSayisi = 0;
        lamba = !lamba;
        digitalWrite(LED_PIN, lamba);
        Serial.println(lamba ? "2. alkis: Lamba acik" : "2. alkis: Lamba kapali");
      } else {
        alkisSayisi = 1;
        ilkAlkis = simdi;
        Serial.println("1. alkis");
      }
    }
    sonSes = simdi;
  }

  // İkinci alkış gecikirse sayımı sıfırla.
  if (alkisSayisi == 1 && simdi - ilkAlkis > ALKIS_ARASI) {
    alkisSayisi = 0;
  }
}
